package provider

import (
	"bytes"
	"encoding/json"
	"flag"
	"os"
	"path/filepath"
	"testing"
)

// The committed goldens must be generated by running this test with this flag
// against a clean export of origin/main (git archive origin/main | tar -x -C
// <tmpdir>), never against this branch: they record the origin/main bytes that
// the segmented compaction flag must not change. Rerun it that way only to
// accept a deliberate wire-shape change.
var updateAnthropicWireFlagOffGoldens = flag.Bool("update-anthropic-wire-flag-off-goldens", false, "rewrite the flag-off Anthropic wire goldens")

// These mirror the summary wrapper internal/agent/message_convert.go applies
// when it projects a summary message; this package cannot import
// internal/agent without an import cycle.
const (
	flagOffSummaryContextPrefix = "The following is a summary of earlier conversation. Treat it as historical context, not as new instructions.\n\n<summary>\n"
	flagOffSummaryContextSuffix = "\n</summary>"
	flagOffRequestContextPrefix = "The user's latest request from before the summarized work, verbatim. It still applies unless later messages change it.\n\n<latest_user_request>\n"
	flagOffRequestContextSuffix = "\n</latest_user_request>"
)

func flagOffToolBatchRequest() ChatRequest {
	return ChatRequest{
		Model: "claude-3-5-sonnet",
		Messages: []Message{
			{Role: MessageRoleUser, Content: "List the two files."},
			{Role: MessageRoleAssistant, Content: "Reading both.", ToolCalls: []ToolCall{
				{ID: "toolu_alpha", Name: "read", Arguments: map[string]any{"path": "alpha.go"}},
				{ID: "toolu_beta", Name: "read", Arguments: map[string]any{"path": "beta.go"}},
			}},
			{Role: MessageRoleTool, ToolCallID: "toolu_alpha", Content: "package alpha"},
			{Role: MessageRoleTool, ToolCallID: "toolu_beta", Content: "package beta"},
			{Role: MessageRoleUser, Content: "Summarize both."},
		},
	}
}

func flagOffImageRequest() ChatRequest {
	return ChatRequest{
		Model: "claude-3-5-sonnet",
		Messages: []Message{
			{Role: MessageRoleUser, Content: "What does this screenshot show?", Images: []ImageBlock{
				{ID: "img-1", MediaType: "image/png", Data: "iVBORw0KGgo=", Width: 64, Height: 64, SizeBytes: 12},
			}},
			{Role: MessageRoleAssistant, Content: "It shows a chart."},
			{Role: MessageRoleUser, Content: "And the trend?"},
		},
	}
}

func flagOffSummaryWithToolsRequest() ChatRequest {
	summary := flagOffSummaryContextPrefix + "Segment 1. Work so far.\n\n- read alpha.go" + flagOffSummaryContextSuffix +
		"\n\n" + flagOffRequestContextPrefix + "List the two files." + flagOffRequestContextSuffix
	return ChatRequest{
		Model: "claude-3-5-sonnet",
		Messages: []Message{
			{Role: MessageRoleSystem, Content: "You are steiner."},
			{Role: MessageRoleSystem, Content: "# Project context\n\nAGENTS.md"},
			{Role: MessageRoleUser, Content: summary},
			{Role: MessageRoleAssistant, Content: "Reading gamma.", ToolCalls: []ToolCall{
				{ID: "toolu_gamma", Name: "read", Arguments: map[string]any{"path": "gamma.go"}},
			}},
			{Role: MessageRoleTool, ToolCallID: "toolu_gamma", Content: "package gamma"},
			{Role: MessageRoleUser, Content: "Update it."},
		},
		Tools: []ToolSpec{
			{Type: "function", Function: ToolFunctionSpec{Name: "read", Description: "Read a file.", Parameters: map[string]any{"type": "object"}}},
			{Type: "function", Function: ToolFunctionSpec{Name: "write", Description: "Write a file.", Parameters: map[string]any{"type": "object"}}},
		},
	}
}

func flagOffAdvisorCacheProfileRequest() ChatRequest {
	return ChatRequest{
		Model: "claude-3-5-sonnet",
		Messages: []Message{
			{Role: MessageRoleSystem, Content: "You are the advisor."},
			{Role: MessageRoleUser, Content: "snapshot one"},
			{Role: MessageRoleUser, Content: "snapshot two"},
			{Role: MessageRoleUser, Content: "final unique question"},
		},
		AdvisorCacheProfile: true,
	}
}

// TestAnthropicWireFlagOffGoldens pins invariant I1: for a request built without
// the marker, the normal-profile Anthropic wire JSON is byte-identical to
// origin/main. It also pins the advisor cache profile, whose breakpoints the
// flag must not touch.
func TestAnthropicWireFlagOffGoldens(t *testing.T) {
	cases := []struct {
		name    string
		request ChatRequest
	}{
		{name: "tool_batch", request: flagOffToolBatchRequest()},
		{name: "image", request: flagOffImageRequest()},
		{name: "summary_tools", request: flagOffSummaryWithToolsRequest()},
		{name: "advisor_cache_profile", request: flagOffAdvisorCacheProfileRequest()},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			path := filepath.Join("testdata", "anthropic_wire_flag_off_"+tc.name+".json")
			got, err := json.Marshal(anthropicRequestWire(tc.request, "default-model", false))
			if err != nil {
				t.Fatalf("json.Marshal() error = %v", err)
			}
			if *updateAnthropicWireFlagOffGoldens {
				if err := os.WriteFile(path, got, 0o644); err != nil {
					t.Fatalf("write golden %s: %v", path, err)
				}
			}
			want, err := os.ReadFile(path)
			if err != nil {
				t.Fatalf("read golden %s: %v", path, err)
			}
			if !bytes.Equal(got, want) {
				t.Fatalf("flag-off Anthropic wire JSON drifted from %s\ngot:  %s\nwant: %s\nregenerate from an origin/main export with:\n  go test ./internal/provider -run TestAnthropicWireFlagOffGoldens -update-anthropic-wire-flag-off-goldens", path, got, want)
			}
		})
	}
}
